content:
760                  return NULL;
   761          }
   762          memset(mov, 0, sizeof(GF_ISOFile));
   763
   764          /*init the boxes*/
   765          mov->TopBoxes = gf_list_new();
   766          if (!mov->TopBoxes) {
   767                  gf_isom_set_last_error(NULL, GF_OUT_OF_MEM);
   768                  gf_free(mov);
   769                  return NULL;
   770          }
   771
   772          /*default storage mode is flat*/
   773          mov->storageMode = GF_ISOM_STORE_FLAT;
   774          mov->es_id_default_sync = -1;
   775          return mov;
   776  }
